import{_ as e,o as l,c as t,a2 as a}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第一篇 · 使用手册：先把我用起来","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/index.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/index.md"}'),i={name:"bluebook/第一篇 使用手册：先把我用起来/index.md"};function r(n,o,s,p,d,u){return l(),t("div",null,[...o[0]||(o[0]=[a('<h1 id="第一篇-·-使用手册-先把我用起来" tabindex="-1">第一篇 · 使用手册：先把我用起来 <a class="header-anchor" href="#第一篇-·-使用手册-先把我用起来" aria-label="Permalink to &quot;第一篇 · 使用手册：先把我用起来&quot;">​</a></h1><blockquote><p>PART 01 · CH. 01—08 · 新手推荐</p></blockquote><p>这一篇解决一个最基础的问题：<strong>momawork-rs 是谁，怎么把它真正用起来。</strong></p><p>很多人第一次面对 AI 助手时，会陷入两种极端：要么把它当搜索引擎，问一句答一句；要么把它当魔法，期待一句话就交付一切。这两种都错过了重点。</p><p>我真正的价值，不在&quot;聊天&quot;，而在<strong>完成任务</strong>。而完成任务的前提，是你知道：</p><ul><li>我能碰你的哪些文件、跑哪些命令（第 3 章）；</li><li>怎么把需求说清楚，让我一次做对（第 2 章）；</li><li>怎么验收一个任务的结果（第 4 章）；</li><li>怎么把成功的方法沉淀下来复用（第 5、6 章）；</li><li>任务太大时，怎么拆解和规划（第 7 章）；</li><li>一个人的算力不够时，怎么召唤一支 AI 团队（第 8 章）。</li></ul><h2 id="本篇学习目标" tabindex="-1">本篇学习目标 <a class="header-anchor" href="#本篇学习目标" aria-label="Permalink to &quot;本篇学习目标&quot;">​</a></h2><p>读完本篇，你将能够：</p><ol><li>独立发起并验收一个真实任务；</li><li>理解我的工作边界：文件、命令、工具、网络；</li><li>加载并复用至少一个 Skill；</li><li>用记忆系统让我越来越懂你；</li><li>知道什么时候该用计划模式、什么时候该开 AI 团队。</li></ol><h2 id="建议节奏" tabindex="-1">建议节奏 <a class="header-anchor" href="#建议节奏" aria-label="Permalink to &quot;建议节奏&quot;">​</a></h2><p>不要一天读完。按&quot;完成一项任务 → 复盘 → 读下一章&quot;的节奏走。每章末尾都有<strong>练习</strong>，挑一个与你现在工作最相关的做掉。</p><blockquote><p>核心心法：<strong>我是一次成功可以复制的助手，但前提是你先完成一次成功。</strong></p></blockquote>',12)])])}const h=e(i,[["render",r]]);export{_ as __pageData,h as default};
